"""Build one offline HTML report from verified local hourly research artifacts."""
from pathlib import Path
import csv
import hashlib
import html
import json
from datetime import datetime
from zoneinfo import ZoneInfo

ROOT=Path(__file__).resolve().parents[1]

def read_sealed(path):
    r=json.loads(path.read_text());raw=json.dumps(r['payload'],sort_keys=True,separators=(',',':'),allow_nan=False).encode()
    if hashlib.sha256(raw).hexdigest()!=r['sha256']: raise ValueError(f'Invalid artifact: {path}')
    return r['payload']

