# Attach a separately frozen test evaluation; never mix test into research ranking.
import argparse
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--test-report',type=Path,default=ROOT/'data/models/hourly-2026-evaluation/7e5b9fed-17f8-483d-bcd2-356df60024e1/report.json')
args=parser.parse_args()
if args.test_report.exists():
    test_path=args.test_report.resolve();test=read_sealed(test_path);tm=test['metrics'];test_dir=test_path.parent
    prediction_path=test_dir/'predictions.csv'
    assert hashlib.sha256(prediction_path.read_bytes()).hexdigest()==test['predictions_sha256']
    assert test['no_fit_performed'] and test['frozen_hashes_unchanged'] and test['expected_hours']==test['scored_hours']
    with prediction_path.open() as stream:forecast_rows=list(csv.DictReader(stream))
    assert len(forecast_rows)==tm['n']
    actual=[float(r['actual_log_return']) for r in forecast_rows];predicted=[float(r['predicted_log_return']) for r in forecast_rows]
    assert abs(sum(abs(a-p) for a,p in zip(actual,predicted))/sum(abs(a) for a in actual)-tm['relative_mae'])<1e-12
    test_gain=(1-tm['relative_mae'])*100
    month_table=''.join(f'<tr><td><b>{esc(m["month"])}</b>{"<small>Tháng chưa hoàn tất: đến 18/10</small>" if m["month"]=="2026-10" else ""}</td><td class="number">{m["n"]:,}</td><td class="number {"red" if m["relative_mae"]>=1 else "green"}"><b>{m["relative_mae"]:.6f}</b></td><td class="number">{m["mae"]:.9f}</td><td class="number">{m["zero_mae"]:.9f}</td><td class="number {"red" if m["relative_mae"]>=1 else "green"}">{(1-m["relative_mae"])*100:.3f}%</td></tr>' for m in test['monthly'])
    test_html=f'''<div id="test2026" style="scroll-margin-top:80px"><div class="panel" style="border-top:4px solid var(--blue);margin:26px 0"><div class="eyebrow blue">TEST 2026 · FROZEN ENSEMBLE · KHÔNG TRAIN LẠI</div><h3 style="font-size:28px;margin-top:12px">Từ đầu 2026 đến nến đã đóng mới nhất</h3><p><b>01/01/2026 00:00 → 18/10/2026 23:00 UTC</b> theo target open. Label cuối đóng <b>19/10/2026 00:00 UTC</b> (07:00 Việt Nam). Đây là snapshot tại lần chạy này; không tự cập nhật nền.</p><div class="metrics"><div class="metric second"><span class="pill blue">Test · không dùng xếp hạng model</span><div class="value blue">{tm['relative_mae']:.6f}</div><b>Relative MAE · {tm['n']:,} giờ</b><p>Coverage 100% khung giờ đã khóa, không loại mẫu. Dự báo cùng target/cutoff để ghép cặp với bạn.</p></div><div class="metric"><span class="pill green">So với zero-return</span><div class="value green">{test_gain:.3f}%</div><b>Giảm lỗi trên test</b><p>MAE model {tm['mae']:.9f}<br>MAE baseline {tm['zero_mae']:.9f}<br>RMSE {tm['rmse']:.9f}</p></div><div class="metric target"><span class="pill red">Chưa đạt 0,97</span><div class="value red">52,964%</div><b>Directional accuracy · chỉ mô tả</b><p>Không dùng để thay tiêu chí MAE. Relative MAE test cao hơn selection 2025: tín hiệu yếu hơn ở kỳ này.</p></div></div><div class="note"><strong>Giữ nguyên mô hình:</strong> hai member, feature schema, coefficient 0,3718555755 / 0,1838885790 và scale /10.000. Không fit, không calibration lại, không chọn model theo kết quả 2026. Ensemble đã học weight Jan–Jun 2025; 2026 từng được xem trong EDA nên đây là <b>test hồi cứu, không phải holdout sạch</b>.</div><div class="tools no-print"><button class="button" id="testCSV">Tải 6.984 dự báo test · CSV</button><a href="#test-monthly" class="button secondary">Kết quả từng tháng ↓</a></div><p class="small">CSV nhúng trong HTML, tải được offline: target_open_time UTC, target_close_time UTC, actual/predicted log-return, zero-return và giá tham chiếu/giá thực tế. So sánh hai model trên cùng timestamp; không so MAE thô giữa hai kỳ có volatility khác nhau.</p></div>
<h3 id="test-monthly" style="scroll-margin-top:80px">Test 2026 theo tháng</h3><div class="table-wrap"><table class="studies"><thead><tr><th>Tháng UTC</th><th>N</th><th>Relative MAE ↓</th><th>MAE model</th><th>MAE baseline</th><th>Giảm lỗi</th></tr></thead><tbody>{month_table}<tr style="background:var(--pale-blue)"><td><b>Toàn bộ test</b></td><td class="number"><b>{tm['n']:,}</b></td><td class="number blue"><b>{tm['relative_mae']:.6f}</b></td><td class="number">{tm['mae']:.9f}</td><td class="number">{tm['zero_mae']:.9f}</td><td class="number green"><b>{test_gain:.3f}%</b></td></tr></tbody></table></div><p class="small" style="margin:12px 0 25px">Đỏ: ngang/kém zero-return (March, May); xanh: tốt hơn. Ratio tổng được tính từ tổng lỗi, không lấy trung bình ratio tháng. March và May chỉ kém baseline rất nhỏ.</p><details class="panel"><summary>Provenance & kiểm tra test 2026</summary><p style="margin-top:12px">{test['source_requests']} REST request, {test['source_bytes']:,} byte record nguồn; mỗi BTC/ETH có 7.154 nến gồm context trước 2026. Chốt end từ giờ server Binance và đồng hồ local; loại nến đang mở. Đã kiểm không gap/trùng, đúng OHLCV, hash nguồn và model; metric tính lại sau nạp CSV; ba forecast rải đầu/giữa/cuối kỳ khớp inference label-free từ 169 nến.</p><code>{esc(str(test_path.relative_to(ROOT)))}</code><p class="small">Predictions SHA-256: {esc(test['predictions_sha256'])}</p><p class="small">Plan/hash model được lưu trước khi tải và chấm test. Bundle frozen được sao chép riêng; không sửa bundle nghiên cứu gốc. Các score bên dưới vẫn là selection 2025, không trộn với test này.</p></details><div class="rule"></div></div>'''
    page=page.replace('<h3>So sánh các hướng nghiên cứu</h3>',test_html+'<h3>So sánh các hướng nghiên cứu · selection 2025</h3>',1)
