    page=page.replace('<span>TEST 2026</span><b>0</b><small>Target dùng trong nghiên cứu này. 2026 đã bị xem trước đó.</small>',f'<span>TEST 2026 · ĐÃ CHẤM RIÊNG</span><b>{tm["n"]:,}</b><small>01/01–18/10/2026 UTC. Giữ model đã khóa; test hồi cứu.</small>',1)
    page=page.replace('Không đọc hoặc chấm target 2026','Không đọc hoặc chấm target 2026 trong search cũ')
    page=page.replace('không dùng target 2026 trong các study nghiên cứu này.','không dùng target 2026 trong 536 biến thể search cũ. Test mới chấm riêng sau khi khóa model.',1)
