    page=page.replace('Các score dưới đây là <b>retrospective selection</b>, chưa phải bằng chứng hiệu quả ngoài mẫu chưa xem.','Bảng research là <b>retrospective selection 2025</b>; mục test mới là <b>retrospective test 2026</b>. Cả hai chưa phải bằng chứng trên holdout sạch chưa xem.',1)
    page=page.replace('0,992930 ≠ 0,970000.','Selection 0,992930 · Test 0,997017 · Target 0,970000.',1)
    page=page.replace('Thời gian làm việc được bộ đếm ghi nhận:','Thời gian làm việc giai đoạn nghiên cứu cũ được bộ đếm ghi nhận:',1)
    data['test_2026']=test
    data['test_forecasts']=[[r['target_open_time'].replace(' ','T'),float(r['actual_log_return']),float(r['predicted_log_return']),float(r['reference_close_usdt']),float(r['actual_close_usdt'])] for r in forecast_rows]
    updated=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
